import {rehabPage} from './rehab-ui.js';
import {libraryPage} from './library-ui.js';
const filters=new Map();
export function programFilter(userId,data){if(['campaigns','library','rehab'].includes(data.module))filters.set(userId+':'+data.module,{language:data.language,category:data.category,region:data.region,contentType:data.contentType,topic:data.topic,format:data.format,view:data.view,sort:data.sort,query:String(data.query||'').slice(0,100)})}
const field=(t,h,name,label,value='',type='text',extra='')=>`<label>${t(label)}<input name="${name}" type="${type}" value="${h(value)}" ${extra}></label>`;
const area=(t,h,name,label,value='',max=1000,required=true)=>`<label>${t(label)}<textarea name="${name}" maxlength="${max}" ${required?'required':''}>${h(value)}</textarea></label>`;
const select=(t,h,name,label,options,value)=>`<label>${t(label)}<select name="${name}" required>${options.map(([v,l])=>`<option value="${h(v)}" ${v===value?'selected':''}>${h(l)}</option>`).join('')}</select></label>`;
const hidden=(h,k,v)=>`<input type="hidden" name="${k}" value="${h(v)}">`;
const form=(t,h,module,operation,body,id='',label='save')=>`<form class="stack" data-form="programs">${hidden(h,'module',module)}${hidden(h,'operation',operation)}${id?hidden(h,'id',id):''}${body}<button class="primary" type="submit">${t(label)}</button></form>`;
const button=(t,h,btn,module,op,id,label,extras='')=>btn(t(label),'programAction',`data-module="${module}" data-op="${op}" data-id="${h(id||'')}" ${extras}`,'secondary');
const noItems=t=>`<p class="empty">${t('noItems')}</p>`;
const formatDate=()=>new Date().toISOString().slice(0,10);
function itemFields(t,h,module,r,scope){
  const input=(n,k,v='',type='text',extra='required')=>field(t,h,n,k,v,type,extra);
  let body=hidden(h,'scope',scope)+input('title','programTitle',r?.title,'text','required maxlength="100"')+area(t,h,'description','programDescription',r?.description,2000)+select(t,h,'language','language',['ar','en','sv'].map(l=>[l,t('lang_'+l)]),r?.language||'en');
  if(module==='library')return body+select(t,h,'category','programCategory',[['book',t('programBook')],['guide',t('programGuide')]],r?.category)+input('author','programAuthor',r?.author,'text','required maxlength="100"')+input('rightsNote','programRights',r?.rightsNote,'text','required maxlength="200"')+area(t,h,'content','programContent',r?.content,12000)+`<label class="check-row"><input name="rights" type="checkbox" required>${t('programRightsConfirm')}</label>`;
  body+=input('start','clubStart',r?.start||formatDate(),'date')+input('end','clubEnd',r?.end||formatDate(),'date');
  if(module==='events')return body+input('time','programTime',r?.time||'18:00','time')+input('location','programLocation',r?.location,'text','required maxlength="160"')+input('minimum','programMinimum',r?.minimum||2,'number','required min="1" max="500"')+input('capacity','programCapacity',r?.capacity||20,'number','required min="1" max="500"');
  return body+select(t,h,'category','programCategory',[['ramadan',t('ramadan')],['startfit',t('startfit')]],r?.category);
}
export function programPage({state,id,t,h,btn}){
  const p=state.programs;if(!p)return '';
  if(id==='masterAdmin'){
    if(!p.canAdmin)return '';
    const refs=['events','campaigns','library','rehab'];
    return `<section class="card stack"><h1>${t(id)}</h1><p>${t('programAdminNotice')}</p><div class="grid">${Object.entries(p.summary).map(([k,v])=>`<div class="stat-box"><b>${v}</b><br>${t(k==='accounts'?'users':k)}</div>`).join('')}</div>${refs.map(m=>`<div class="row rule wrap"><b class="grow">${t(m)}</b>${button(t,h,btn,m,'flag','',p.flags[m]?'programDisable':'programEnable',`data-enabled="${!p.flags[m]}"`)}${btn(t(m),'nav',`data-id="${m}"`,'chip')}</div>`).join('')}${btn(t('identity'),'nav','data-id="identity"','secondary')}${state.me.role==='admin'?btn(t('admin'),'nav','data-id="admin"','secondary'):''}<h2>${t('audit')}</h2>${p.audit.map(a=>`<div class="rule"><b>${h(a.operation)}</b> · ${t(a.module)} · ${h(new Date(a.at).toLocaleString())}</div>`).join('')||noItems(t)}</section>`;
  }
  if(!p.flags[id]&&!p.canAdmin)return `<div class="notice">${t('programDisabled')}</div>`;
  if(id==='rehab')return rehabPage({state,t,h,btn,filter:filters.get(state.me.id+':rehab')||{}});
  if(id==='library')return libraryPage({state,t,h,btn,filter:filters.get(state.me.id+':library')||{}});
  const scope=p.canAdmin?'public':p.canClubEvents&&id==='events'?'club':null;
  const filter=filters.get(state.me.id+':'+id)||{};const rows=p.items.filter(r=>r.module===id&&(!filter.language||r.language===filter.language)&&(!filter.category||r.category===filter.category)&&(!filter.query||[r.title,r.description,r.author].some(x=>String(x||'').toLowerCase().includes(filter.query.toLowerCase()))));
  return `<section class="card stack"><h1>${t(id)}</h1><p class="notice">${t('programLocalNotice')}</p>${id!=='events'?`<form class="row wrap" data-form="programFilter">${hidden(h,'module',id)}${field(t,h,'query','programSearch',filter.query||'','search')}${select(t,h,'language','language',[['',t('all')],...['ar','en','sv'].map(l=>[l,t('lang_'+l)])],filter.language||'').replace(' required','')}${select(t,h,'category','programCategory',[['',t('all')],...(id==='library'?[['book',t('programBook')],['guide',t('programGuide')]]:[['ramadan',t('ramadan')],['startfit',t('startfit')]])],filter.category||'').replace(' required','')}<button class="secondary" type="submit">${t('programSearch')}</button></form>`:''}${scope?`<details><summary>${t('create')}</summary>${form(t,h,id,'create',itemFields(t,h,id,null,scope),'','create')}</details>`:''}${rows.map(r=>`<article class="rule stack"><div class="row space wrap"><h3>${h(r.title)}</h3><span class="badge gold">${t('programStatus_'+(r.eventStatus||r.status))}</span></div><p>${h(r.description)}</p><small>${h(r.language.toUpperCase())} ${r.category?t(r.category==='book'?'programBook':r.category==='guide'?'programGuide':r.category):''}</small>${id==='library'?`<small>${h(r.author)} · ${h(r.rightsNote)}</small><details><summary>${t('programContent')}</summary><p class="post-text">${h(r.content)}</p></details>${button(t,h,btn,id,'download',r.id,'programDownload')}`:`<small>${h(r.start)} — ${h(r.end)} · ${r.count} ${t('programParticipants')}</small>${id==='events'?`<p>${h(r.location)} · ${h(r.time)} UTC · ${r.count}/${r.capacity} (${t('programMinimum')}: ${r.minimum}) · ${t('programWaitlist')}: ${r.waitCount}${r.waiting?' · '+t('programWaiting'):''}</p>`:''}${r.status==='published'&&!p.canAdmin?button(t,h,btn,id,r.joined?'leave':'join',r.id,r.joined?'leave':'join'):''}${r.joined&&id==='campaigns'?`<small>${r.checkins.length} ${t('done')}</small>${button(t,h,btn,id,'checkin',r.id,'checkin')}`:''}`}${r.manage?`<div class="row wrap">${button(t,h,btn,id,r.status==='published'?'draft':'publish',r.id,r.status==='published'?'programUnpublish':'programPublish')}${button(t,h,btn,id,'archive',r.id,'programArchive')}</div><details><summary>${t('wellnessEdit')}</summary>${form(t,h,id,'update',itemFields(t,h,id,r,r.clubId?'club':'public'),r.id)}</details>${(r.roster||[]).map(e=>`<div class="row rule"><span class="grow">${h(e.name)} · ${e.waiting?t('programWaiting'):e.checkins}</span>${id==='events'&&!e.waiting?button(t,h,btn,id,'attendance',r.id,e.attended?'programAbsent':'programAttended',`data-target="${h(e.id)}" data-attended="${!e.attended}"`):''}</div>`).join('')}`:''}</article>`).join('')||noItems(t)}</section>`;
}
export function programPayload(data){const p={...data};for(const k of ['minimum','capacity','progress'])if(Object.hasOwn(p,k))p[k]=Number(p[k]);if(Object.hasOwn(p,'discomfort'))p.discomfort=p.discomfort===''?null:Number(p.discomfort);if(Object.hasOwn(p,'rights'))p.rights=p.rights==='on';if(Object.hasOwn(p,'confirm'))p.confirm=p.confirm==='on';if(p.linkId==='none')p.linkId=null;return p;}
